import { Component, computed, input } from '@angular/core';
import { TablerIconComponent, IconTrendingUp, IconTrendingDown, IconMinus } from '@tabler/icons-angular';

/** hrm-trend-cell — giá trị + biến động có mũi tên ↑/↓. Tăng=lục, giảm=đỏ, không đổi=xám.
 *  `delta` là số (âm/dương); hiển thị kèm `unit` ('%' hoặc đơn vị khác). */
@Component({
  selector: 'hrm-trend-cell',
  imports: [TablerIconComponent],
  template: `
    @if (showValue() && value() !== '') { <span class="tr-val">{{ value() }}</span> }
    <span class="tr-delta" [attr.data-dir]="dir()">
      <tabler-icon [icon]="icon()" [size]="14" />
      <span class="tr-num">{{ deltaDisplay() }}</span>
    </span>
  `,
  host: { class: 'hrm-trend-cell' },
  styles: [`
:host { display: inline-flex; align-items: center; gap: 8px; }
.tr-val { font-size: var(--fs-14); color: var(--text-strong); font-variant-numeric: tabular-nums; }
.tr-delta { display: inline-flex; align-items: center; gap: 2px; font-size: var(--fs-13); font-weight: 500;
  font-variant-numeric: tabular-nums; }
.tr-delta[data-dir='up']   { color: var(--success-base); }
.tr-delta[data-dir='down'] { color: var(--error-base); }
.tr-delta[data-dir='flat'] { color: var(--text-sub); }
  `],
})
export class HrmTrendCell {
  /** Giá trị chính hiển thị trước biến động (tùy chọn). */
  readonly value = input<string | number>('');
  readonly delta = input(0);
  readonly unit = input('%');
  readonly showValue = input(true);

  protected readonly dir = computed(() => (this.delta() > 0 ? 'up' : this.delta() < 0 ? 'down' : 'flat'));
  protected readonly icon = computed(() =>
    this.delta() > 0 ? IconTrendingUp : this.delta() < 0 ? IconTrendingDown : IconMinus,
  );
  protected readonly deltaDisplay = computed(() => {
    const d = this.delta();
    const sign = d > 0 ? '+' : d < 0 ? '−' : '';
    return `${sign}${Math.abs(d)}${this.unit()}`;
  });
}
